          "https://media.ffycdn.net/eu/scout24/EUDYRGvS6oqwWcNY4RGa.jpg?cid=frontify-mcp",
          "https://media.ffycdn.net/eu/scout24/6Me2cFcDnbAvWxNhgi1z.png?cid=frontify-mcp"
